package org.joda.time;

import java.io.*;
import java.io.Serializable;
import java.math.*;
import java.util.*;
import org.joda.convert.FromString;
import org.joda.time.base.BasePeriod;
import org.joda.time.chrono.ISOChronology;
import org.joda.time.field.FieldUtils;
import org.joda.time.format.ISOPeriodFormat;
import org.joda.time.format.PeriodFormatter;
import org.junit.*;
import org.junit.Test;
import static org.junit.Assert.*;

public class Period_normalizedStandard_TriageGen2Test {

    @Test
    public void testNormalizedStandard_SimpleDuration() {
        // Test with a simple period that doesn't involve years/months
        Period period = new Period(1, 2, 3, 4, 5, 6, 7, 8);
        PeriodType type = PeriodType.standard();
        Period result = period.normalizedStandard(type);

        assertEquals(0, result.getYears());
        assertEquals(0, result.getMonths());
        assertEquals(1, result.getWeeks());
        assertEquals(2, result.getDays());
        assertEquals(3, result.getHours());
        assertEquals(4, result.getMinutes());
        assertEquals(5, result.getSeconds());
        assertEquals(6, result.getMillis());
    }

    @Test
    public void testNormalizedStandard_WithYearsAndMonthsSupported() {
        // Test normalization where years and months are supported by the type
        Period period = new Period(1, 2, 0, 0, 0, 0, 0, 0, PeriodType.standard());
        PeriodType type = PeriodType.standard(); // supports years and months
        Period result = period.normalizedStandard(type);

        assertEquals(1, result.getYears());
        assertEquals(2, result.getMonths());
    }

    @Test
    public void testNormalizedStandard_YearsOnlyType() {
        // Test where only years are supported
        Period period = new Period(1, 2, 0, 0, 0, 0, 0, 0);
        // Create a type that only supports years (using a custom logic or existing type if available)
        // Since PeriodType is often immutable, we assume standard() supports both.
        // To test the branch where months are NOT supported but years ARE:
        PeriodType yearType = new PeriodType(DurationFieldType.YEARS_TYPE);

        Period result = period.normalizedStandard(yearType);

        // 1 year, 2 months = 14 months. 14 / 12 = 1 year. Remainder 2 months.
        // Since months are not supported, it should throw exception if totalMonths != 0
        try {
            period.normalizedStandard(yearType);
            fail("Should have thrown UnsupportedOperationException due to remaining months");
        } catch (UnsupportedOperationException e) {
            assertTrue(e.getMessage().contains("Unable to normalize"));
        }
    }

    @Test
    public void testNormalizedStandard_MonthsOnlyType() {
        // Test where only months are supported
        Period period = new Period(1, 2, 0, 0, 0, 0, 0, 0);
        PeriodType monthType = new PeriodType(DurationFieldType.MONTHS_TYPE);

        // 1 year, 2 months = 14 months.
        // totalMonths = 14. 
        // Years not supported.
        // Months supported -> normalizedMonths = 14.
        // totalMonths becomes 0.
        Period result = period.normalizedStandard(monthType);
        assertEquals(14, result.getMonths());
        assertEquals(0, result.getYears());
    }

    @Test
    public void testNormalizedStandard_NoYearsOrMonthsInSource() {
        // Test the branch where years == 0 and months == 0
        Period period = new Period(0, 0, 1, 1, 1, 1, 1, 1);
        PeriodType type = PeriodType.standard();
        Period result = period.normalizedStandard(type);

        assertEquals(1, result.getWeeks());
        assertEquals(1, result.getDays());
        assertEquals(1, result.getHours());
        assertEquals(1, result.getMinutes());
        assertEquals(1, result.getSeconds());
        assertEquals(1, result.getMillis());
    }

    @Test
    public void testNormalizedStandard_UnsupportedOperationException() {
        // Test the case where years/months exist but type cannot represent the remainder
        // 1 year, 1 month, 1 day. Type only supports days.
        Period period = new Period(1, 1, 0, 1, 0, 0, 0, 0);
        PeriodType dayType = new PeriodType(DurationFieldType.DAYS_TYPE);

        try {
            period.normalizedStandard(dayType);
            fail("Expected UnsupportedOperationException");
        } catch (UnsupportedOperationException e) {
            assertTrue(e.getMessage().contains("Unable to normalize"));
        }
    }

    @Test
    public void testNormalizedStandard_LargeValues() {
        // Test with large values to ensure long arithmetic is used (as per code comments)
        // 1000000 weeks
        Period period = new Period(0, 0, 1000000, 0, 0, 0, 0, 0);
        PeriodType type = PeriodType.standard();
        Period result = period.normalizedStandard(type);

        // Since standard type includes weeks, it should be preserved
        assertEquals(1000000, result.getWeeks());
    }

    @Test
    public void testNormalizedStandard_ZeroPeriod() {
        Period period = new Period(0, 0, 0, 0, 0, 0, 0, 0);
        PeriodType type = PeriodType.standard();
        Period result = period.normalizedStandard(type);

        assertEquals(0, result.getYears());
        assertEquals(0, result.getMonths());
        assertEquals(0, result.getDays());
    }
}
